window.AUTH=window.AUTH||{};window.AUTH["17-965"]={"d":"17-965","id":"2017/17-965","n":"Trump v. Hawaii","briefs":[{"k":"petitioner","label":"Brief of petitioners Donald J. Trump, President of the United States, et al.","date":"2018-02-21","url":"https://www.supremecourt.gov/DocketPDF/17/17-965/36179/20180221201616615_17-965tsUnitedStates.pdf","side":"pet","n":150},{"k":"respondent","label":"Brief of respondents State of Hawaii, et al.","date":"2018-03-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-965/39833/20180323141105422_17-965bs--Merits%20Response--AS%20FILED.pdf","side":"res","n":138},{"k":"reply","label":"Reply of petitioners Donald J. Trump, President of the United States, et al.","date":"2018-04-18","url":"https://www.supremecourt.gov/DocketPDF/17/17-965/43794/20180418113221228_17-965rbUnitedStates.pdf","side":"pet","n":67}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Abourezk v. Reagan","cite":"785 F.2d 1043","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/785/1043/","sum":"Stating that Section 1182(f) “provides a safeguard against the danger posed by any particular case or class of cases that is not covered by one of the categories in section 1182(a)” (emphasis added).","sumSrc":"brief:1","by":{"0":"21, 31, 44","1":"36","2":"7, 14"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"0":"29","2":"6"}},{"t":"case","label":"Allende v. Shultz","cite":"845 F.2d 1111","y":1988,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/845/1111/","by":{"0":"44"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"46","1":"4, 5, 30, 52"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"135 S. Ct. 1378","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"26","1":"20, 26"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"sum":"Under § 10 of the Administrative Procedure Act, an alien whose exclusion has been ordered administratively under the Immigration and Nationality Act of 1952, and who neither claims citizenship nor holds a certificate of identity issued under § 360 (b) of that Act, may obtain judicial review of such order by an action in a federal district court for a declaratory judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"24","2":"2"}},{"t":"case","label":"Chicago & S. Air Lines, Inc. v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"0":"39"}},{"t":"case","label":"Church of the Lukumi Babalu Aye, Inc. v. City of Hialeah","cite":"508 U.S. 520","y":1993,"id":"1992/91-948","sc":1,"sum":"The Court found that an ordinance banning religious animal sacrifice was unconstitutional under the Free Exercise Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"65","1":"passim","2":"26"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"72, 73","1":"78"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"0":"46","1":"51, 61"}},{"t":"case","label":"Crosby v. National Foreign Trade Council","cite":"530 U.S. 363","y":2000,"id":"1999/99-474","sc":1,"sum":"The Court held that \"the state Act is preempted, and its application unconstitutional, under the Supremacy Clause.\" Justice Souter wrote for the Court that Massachusetts' law created an obstacle to the President's discretion to control economic sanctions against Burma, interfered with Congress's intention to limit economic pressure against the Burmese Government, and was at odds with the President's authority to speak for the United States among the world's nations to develop a comprehensive, multilateral Burma strategy.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"0":"72","1":"78"}},{"t":"case","label":"Dalton v. Specter","cite":"511 U.S. 462","y":1994,"id":"1993/93-289","sc":1,"sum":"Judicial review is not available for respondents' claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","1":"24","2":"4"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"sum":"The Court held, 6-3, that the Immigration and Nationality Act does not deprive the federal courts of jurisdiction to grant habeas relief to aliens challenging their detention under section 1226(c) and, 5-4, that detention during removal proceedings is a constitutionally permissible part of that process.","sumSrc":"Oyez","by":{"0":"59"}},{"t":"case","label":"Department of the Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"sum":"In an appeal pursuant to § 7513, the Board does not have authority to review the substance of an underlying security-clearance determination in the course of reviewing an adverse action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54"}},{"t":"case","label":"Eisen v. Carlisle & Jacquelin","cite":"417 U.S. 156","y":1974,"id":"1973/73-203","sc":1,"sum":"Petitioner brought a class action under Fed. Rule Civ. Proc. 23 on behalf of himself and all odd-lot traders on the New York Stock Exchange for a certain four-year period, charging respondent brokerage firms, which handled 99% of the Exchange's odd-lot business, and respondent Exchange with violating the antitrust and securities laws. There followed a series of decisions by the District Court and the Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"76"}},{"t":"case","label":"Elk Grove Unified Sch. Dist. v. Newdow","cite":"542 U.S. 1","y":2004,"id":"2003/02-1624","sc":1,"sum":"The Court held that a divorced father did not have sufficient custody of his daughter to challenge the Establishment Clause of the First Amendment on her behalf.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Fiallo v. Bell","cite":"430 U.S. 787","y":1977,"id":"1976/75-6297","sc":1,"sum":"Sections 101 (b) (1) (D) and 101 (b) (2) of the Immigration and Nationality Act of 1952, which have the effect of excluding the relationship between an illegitimate child and his natural father (as opposed to his natural mother) from the special preference immigration status accorded by the Act to the \"child\" or \"parent\" of a United States citizen or lawful permanent resident, held not to be unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 21, 59","1":"passim","2":"3, 12, 22"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Galvan v. Press","cite":"347 U.S. 522","y":1954,"id":"scdb/1953-075","sc":1,"sum":"1. Section 22 of the Internal Security Act of 1950, providing for the deportation of any alien who has been a member of the Communist Party at any time after entry, is constitutional-as here applied to a resident alien shown to have been willingly a member of the Communist Party from 1944 to 1946 although not shown to have been aware of its advocacy of violent overthrow of the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","1":"4, 30, 52"}},{"t":"case","label":"Grupo Mexicano de Desarrollo S. A. v. Alliance Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"0":"72"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"by":{"0":"18","1":"22"}},{"t":"case","label":"Hawaii v. Trump","cite":"859 F.3d 741","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/859/741/","by":{"0":"6"}},{"t":"case","label":"Hein v. Freedom From Religion Found., Inc.","cite":"551 U.S. 587","y":2007,"id":"2006/06-157","sc":1,"sum":"By a 5-4 vote, the Court ruled that citizens do not have standing as taxpayers to bring Establishment Clause challenges against Executive Branch programs that are funded by appropriations for general administrative expenses.","sumSrc":"Oyez","by":{"0":"67","1":"29","2":"5"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"55","1":"19","2":"25"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"46","1":"passim"}},{"t":"case","label":"IRAP v. Trump","cite":"857 F.3d 554","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/857/554/","by":{"0":"5"}},{"t":"case","label":"Kent v. Dulles","cite":"357 U.S. 116","y":1958,"id":"1957/481","sc":1,"sum":"In a 5-to-4 decision, the Court held that the right to travel is an inherent element of \"liberty\" that cannot be denied to American citizens.","sumSrc":"Oyez","by":{"0":"47","1":"34, 39","2":"11"}},{"t":"case","label":"Kerry v. Din","cite":"135 S. Ct. 2128","y":2015,"id":"2014/13-1402","sc":1,"sum":"The Court held that the lack of a detailed explanation for a denial of a visa application does not violate the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"27, 61, 62, 63","1":"passim","2":"23, 24"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"22, 23"}},{"t":"case","label":"Legal Assistance for Vietnamese Asylum Seekers v. Department of State","cite":"45 F.3d 469","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/45/469/","by":{"0":"25, 52","1":"25, 54, 60"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"0":"72"}},{"t":"case","label":"Lujan v. National Wildlife Fed’n","cite":"497 U.S. 871","y":1990,"id":"1989/89-640","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Supreme Court held that NWF did not have standing to challenge the land-use designations. The two timely affidavits were not enough to show that the group members had actually been affected by the BLM decisions.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Madsen v. Women’s Health Ctr., Inc.","cite":"512 U.S. 753","y":1994,"id":"1993/93-880","sc":1,"sum":"In a majority opinion authored by Chief Justice William H. Rehnquist, the Court found that the state of Florida could only restrict protesters to the extent necessary to allow the clinic to run and the staff to live in their homes without interference.","sumSrc":"Oyez","by":{"0":"72","1":"77, 78"}},{"t":"case","label":"McCreary County v. ACLU of Ky.","cite":"545 U.S. 844","y":2005,"id":"2004/03-1693","sc":1,"ar":2,"sum":"The Court found the display of the Ten Commandments in public schools and courthouses violated the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"passim","1":"68, 71, 74","2":"25"}},{"t":"case","label":"McGowan v. Maryland","cite":"366 U.S. 420","y":1961,"id":"1960/8","sc":1,"sum":"The Court found that the blue laws did not violate the Free Exercise Clause because the employees allege only economic injury and not infringement on their own religious practices. The Court also found that the blue laws did not violate the division between church and state.","sumSrc":"Oyez","by":{"0":"27, 28, 65","1":"27, 28, 29","2":"5, 27"}},{"t":"case","label":"Milner v. Department of the Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Morfin v. Tillerson","cite":"851 F.3d 710","y":2017,"url":"https://www.courtlistener.com/c/F.3d/851/710/","by":{"0":"62"}},{"t":"case","label":"Nademi v. INS","cite":"679 F.2d 811","y":1982,"url":"https://www.courtlistener.com/c/F.2d/679/811/","by":{"0":"53"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"55, 56"}},{"t":"case","label":"Nishimura Ekiu v. United States","cite":"142 U.S. 651","y":1892,"id":"scdb/1891-092","sc":1,"sum":"The act of March 3, 1891, c. 551, forbidding certain classes of alien immigrants to land in the United States, is constitutional and valid.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"18, 22","1":"22, 23"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"67"}},{"t":"case","label":"Pittston Coal Grp. v. Sebben","cite":"488 U.S. 105","y":1988,"id":"1988/87-821","sc":1,"sum":"The Black Lung Benefits Reform Act of 1977 (BLBRA), in 30 U. S. C. § 902(f)(2), provided that, pending the issuance of permanent regulations by the Secretary of Labor, cases filed or pending, as well as certain claims required to be reopened or readjudicated, were to be assessed under \"[c]riteria... not... more restrictive than the criteria applicable to a claim filed on June 30, 1973.\" As of that date, under …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"0":"36, 59, 67, 69","1":"63","2":"9, 21, 24, 26"}},{"t":"case","label":"Saavedra Bruno v. Albright","cite":"197 F.3d 1153","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/197/1153/","by":{"0":"19, 20, 21, 23, 25","1":"23","2":"2"}},{"t":"case","label":"Sale v. Haitian Ctrs. Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"ar":2,"sum":"And, it found that both section 243(h) and Article 33 are silent regarding extraterritorial application. In fact, the language of both suggests that only individuals who have already arrived on United States soil are protected, and their use throughout history confirms this interpretation. Thus, the judgment of the Court of Appeals is reversed.","sumSrc":"Oyez","by":{"0":"22, 50","1":"21","2":"3"}},{"t":"case","label":"Sessions v. Morales-Santana","cite":"137 S. Ct. 1678","y":2017,"id":"2016/15-1191","sc":1,"sum":"The Court held that statutory distinction between the physical presence requirements for transferral of derivative citizenship for unwed citizen mothers and unwed citizen fathers of foreign-born children violates the Equal Protection Clause of the Fifth Amendment, and it is up to Congress, rather than the courts, to create a uniform solution that does not disadvantage any person on the basis of gender.","sumSrc":"Oyez","by":{"0":"58, 61","1":"64","2":"23"}},{"t":"case","label":"Shaughnessy v. United States ex rel. Mezei","cite":"345 U.S. 206","y":1953,"id":"scdb/1952-067","sc":1,"sum":"The Attorney General's continued exclusion of the alien without a hearing does not amount to an unlpvful detention, and courts may not temporarily admit him to the iJnited States pending arrangements for his departure abroad.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Texas v. United States","cite":"809 F.3d 134","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/809/134/","ar":1,"by":{"0":"74"}},{"t":"case","label":"Thompson v. North Am. Stainless, LP","cite":"562 U.S. 170","y":2011,"id":"2010/09-291","sc":1,"sum":"The Court held that an employer violates Title VII of the Civil Rights Acts by firing the fiancee of an employee who complains about workplace discrimination.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Town of Chester v. Laroe Estates, Inc.","cite":"137 S. Ct. 1645","y":2017,"id":"2016/16-605","sc":1,"sum":"The Court determined that an intervenor to a lawsuit must meet the requirements of Article III standing if the intervenor wishes to pursue relief that was not already requested by the plaintiff.","sumSrc":"Oyez","by":{"0":"72"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 377","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./138/377/","sc":1,"by":{"0":"6","1":"10"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 542","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./138/542/","sc":1,"by":{"0":"2, 11, 13"}},{"t":"case","label":"United States v. Chemical Found., Inc.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"sum":"1. A decree of the Circuit Court of Appeals, entered prior to the taking effect of the Jurisdictional Act of February 13, 1925, and affirming dismissal on the merits of a bill by the United States to set aside, as unauthorized and fraudulently procured, sales of patent and other rights and properties seized pursuant to the Trading, with the Enemy Act, was reviewable by this Court on appeal (Jud. Code §§ 128, 241). …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"68","1":"75"}},{"t":"case","label":"United States v. Curtiss-Wright Exp. Corp.","cite":"299 U.S. 304","y":1936,"id":"1900-1940/299us304","sc":1,"sum":"The Court held that the President has greater legislative power in international affairs than would be allowed in domestic ones.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"United States v. Mendoza","cite":"464 U.S. 154","y":1984,"id":"1983/82-849","sc":1,"sum":"The United States may not be collaterally estopped on an issue such as the one involved here, adjudicated against it in an earlier lawsuit brought by a different party.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"75"}},{"t":"case","label":"United States v. Munsingwear, Inc.","cite":"340 U.S. 36","y":1950,"id":"scdb/1950-004","sc":1,"sum":"The dismissal is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"0":"67"}},{"t":"case","label":"United States v. Verdugo-Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"sum":"The text of the Fourth Amendment concerns \"the people,\" suggesting a concern with persons who are part of the national community, as contrasted with aliens without any substantial connection to the U.S. Moreover, extraterritorial aliens are not even entitled to rights under the Fifth Amendment, which speaks in the relatively more universal term of \"person.\" And non-\"fundamental\" rights are not even guaranteed to inhabitants of unincorporated territories under U.S sovereign control, much less aliens.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"United States v. Witkovich","cite":"353 U.S. 194","y":1957,"id":"1956/295","sc":1,"sum":"Construing clause (3) of § 242 (d) in the context of the entire Section and of the scheme of the legislation as a whole, with due regard to the principle of so construing statutes as to avoid raising constitutional questions, the information an alien is required to furnish under clause (3) relates solely to his availability for deportation; and dismissal of the indictment for failure to state an offense is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","1":"35"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"sum":"This action was authorized by the Act of June 21, 1941, 22 U. S. C. § 223, and the proclamations and regulations issued thereunder, notwithstanding the War Brides Act of December 28, 1945, 8 U. S. C. § 232 et seq.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"22, 23, 52, 53","2":"2, 10, 11, 12, 25"}},{"t":"case","label":"United States R.R. Ret. Bd. v. Fritz","cite":"449 U.S. 166","y":1980,"id":"1980/79-870","sc":1,"sum":"The Court held that laws may create classifications that are not elegant or “artfully drawn” but that are not unconstitutional. The Constitution would allow Congress to deny windfall benefits to all employees, therefore it was not unconstitutional to deny them to some.","sumSrc":"Oyez","by":{"0":"61","2":"23"}},{"t":"case","label":"Valley Forge Christian Coll. v. Americans United for Separation of Church & State, Inc.","cite":"454 U.S. 464","y":1982,"id":"1981/80-327","sc":1,"ar":1,"sum":"The Court held that Americans United for Separation of Church and State did not have standing to sue. Justice Rehnquist argued that the group did not pass the first prong of the Court's test for taxpayer standing.","sumSrc":"Oyez","by":{"0":"29","1":"30","2":"4, 6"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 26, 35, 36"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"ar":2,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"0":"48","1":"21, 32, 50"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"47","1":"35"}},{"t":"case","label":"Zemel v. Rusk","cite":"381 U.S. 1","y":1965,"id":"1964/86","sc":1,"sum":"After this country had broken diplomatic relations with Cula and the Department of State had eliminated Cuba from the area for which passports were not required, appellant applied to have his passport validated for travel to Cuba \"to satisfy [his] curiosity... and to make [him] a better informed citizen.\" His request was denied, and he filed suit in federal district court seeking a judgment declaring that he was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","1":"52"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"36","1":"62"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"0":"21","1":"21"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"135 S. Ct. 2076","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"0":"46, 47, 60","1":"53"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"54"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"17, 72"}},{"t":"const","label":"Amendment I, Section 1","clauses":[["establishment","Establishment Clause"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"32"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(b)","(1994)"],"by":{"0":"20, 20"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(27)","(a)(4)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"57, 3, 3","2":"19"}},{"t":"usc","label":"8 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/8/1151","subs":["(b)"],"by":{"0":"57"}},{"t":"usc","label":"8 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/8/1153","subs":["(a)","(c)(2)(A)"],"stext":{"head":"§1153. Allocation of immigrant visas","paras":[[0,"(a) Preference allocation for family-sponsored immigrants"],[0,"Aliens subject to the worldwide level specified in section 1151(c) of this title for family-sponsored immigrants shall be allotted visas as follows:"],[0,"(1) Unmarried sons and daughters of citizens"],[1,"Qualified immigrants who are the unmarried sons or daughters of citizens of the United States shall be allocated visas in a number not to exceed 23,400, plus any visas not required for the class specified in paragraph (4)."],[0,"(2) Spouses and unmarried sons and unmarried daughters of permanent resident aliens"],[1,"Qualified immigrants—"],[2,"(A) who are the spouses or children of an alien lawfully admitted for permanent residence, or"],[2,"(B) who are the unmarried sons or unmarried daughters (but are not the children) of an alien lawfully admitted for permanent residence,"],[1,"shall be allocated visas in a number not to exceed 114,200, plus the number (if any) by which such worldwide level exceeds 226,000, plus any visas not required for the class specified in paragraph (1); except that not less than 77 percent of such visa numbers shall be allocated to aliens described in subparagraph (A)."],[0,"(3) Married sons and married daughters of citizens"],[1,"Qualified immigrants who are the married sons or married daughters of citizens of the United States shall be allocated visas in a number not to exceed 23,400, plus any visas not required for the classes specified in paragraphs (1) and (2)."],[0,"(4) Brothers and sisters of citizens"],[1,"Qualified immigrants who are the brothers or sisters of citizens of the United States, if such citizens are at least 21 years of age, shall be allocated visas in a number not to exceed 65,000, plus any visas not required for the classes specified in paragraphs (1) through (3)."],[0,"(b) Preference allocation for employment-based immigrants"],[0,"Aliens subject to the worldwide level specified in section 1151(d) of this title for employment-based immigrants in a fiscal year shall be allotted visas as follows:"],[0,"(1) Priority workers"],[1,"Visas shall first be made available in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraphs (4) and (5), to qualified immigrants who are aliens described in any of the following subparagraphs (A) through (C):"],[0,"(A) Aliens with extraordinary ability"],[2,"An alien is described in this subparagraph if—"],[3,"(i) the alien has extraordinary ability in the sciences, arts, education, business, or athletics which has been demonstrated by sustained national or international acclaim and whose achievements have been recognized in the field through extensive documentation,"],[3,"(ii) the alien seeks to enter the United States to continue work in the area of extraordinary ability, and"],[3,"(iii) the alien's entry into the United States will substantially benefit prospectively the United States."],[0,"(B) Outstanding professors and researchers"],[2,"An alien is described in this subparagraph if—"],[3,"(i) the alien is recognized internationally as outstanding in a specific academic area,"],[3,"(ii) the alien has at least 3 years of experience in teaching or research in the academic area, and"],[3,"(iii) the alien seeks to enter the United States—"],[4,"(I) for a tenured position (or tenure-track position) within a university or institution of higher education to teach in the academic area,"],[4,"(II) for a comparable position with a university or institution of higher education to conduct research in the area, or"],[4,"(III) for a comparable position to conduct research in the area with a department, division, or institute of a private employer, if the department, division, or institute employs at least 3 persons full-time in research activities and has achieved documented accomplishments in an academic field."],[0,"(C) Certain multinational executives and managers"],[2,"An alien is described in this subparagraph if the alien, in the 3 years preceding the time of the alien's application for classification and admission into the United States under this subparagraph, has been employed for at least 1 year by a firm or corporation or other legal entity or an affiliate or subsidiary thereof and the alien seeks to enter the United States in order to continue to render services to the same employer or to a subsidiary or affiliate thereof in a capacity that is managerial or executive."],[0,"(2) Aliens who are members of the professions holding advanced degrees or aliens of exceptional ability"],[0,"(A) In general"],[2,"Visas shall be made available, in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraph (1), to qualified immigrants who are members of the professions holding advanced degrees or their equivalent or who because of their exceptional ability in the sciences, arts, or business, will substantially benefit prospectively the national economy, cultural or educational interests, or welfare of the United States, and whose services in the sciences, arts, professions, or business are sought by an employer in the United States."],[0,"(B) Waiver of job offer"],[0,"(i) National interest waiver"],[3,"Subject to clause (ii), the Attorney General may, when the Attorney General deems it to be in the national interest, waive the requirements of subparagraph (A) that an alien's services in the sciences, arts, professions, or business be sought by an employer in the United States."],[0,"(ii) Physicians working in shortage areas or veterans facilities"],[0,"(I) In general"],[4,"The Attorney General shall grant a national interest waiver pursuant to clause (i) on behalf of any alien physician with respect to whom a petition for preference classification has been filed under subparagraph (A) if—"],[5,"(aa) the alien physician agrees to work full time as a physician in an area or areas designated by the Secretary of Health and Human Services as having a shortage of health care professionals or at a health care facility under the jurisdiction of the Secretary of Veterans Affairs; and"],[5,"(bb) a Federal agency or a department of public health in any State has previously determined that the alien physician's work in such an area or at such facility was in the public interest."],[0,"(II) Prohibition"],[4,"No permanent resident visa may be issued to an alien physician described in subclause (I) by the Secretary of State under section 1154(b) of this title, and the Attorney General may not adjust the status of such an alien physician from that of a nonimmigrant alien to that of a permanent resident alien under section 1255 of this title, until such time as the alien has worked full time as a physician for an aggregate of 5 years (not including the time served in the status of an alien described in section 1101(a)(15)(J) of this title), in an area or areas designated by the Secretary of Health and Human Services as having a shortage of health care professionals or at a health care facility under the jurisdiction of the Secretary of Veterans Affairs."],[0,"(III) Statutory construction"],[4,"Nothing in this subparagraph may be construed to prevent the filing of a petition with the Attorney General for classification under section 1154(a) of this title, or the filing of an application for adjustment of status under section 1255 of this title, by an alien physician described in subclause (I) prior to the date by which such alien physician has completed the service described in subclause (II)."],[0,"(IV) Effective date"],[4,"The requirements of this subsection do not affect waivers on behalf of alien physicians approved under subsection (b)(2)(B) before the enactment date of this subsection. In the case of a physician for whom an application for a waiver was filed under subsection (b)(2)(B) prior to November 1, 1998, the Attorney General shall grant a national interest waiver pursuant to subsection (b)(2)(B) except that the alien is required to have worked full time as a physician for an aggregate of 3 years (not including time served in the status of an alien described in section 1101(a)(15)(J) of this title) before a visa can be issued to the alien under section 1154(b) of this title or the status of the alien is adjusted to permanent resident under section 1255 of this title."],[0,"(C) Determination of exceptional ability"],[2,"In determining under subparagraph (A) whether an immigrant has exceptional ability, the possession of a degree, diploma, certificate, or similar award from a college, university, school, or other institution of learning or a license to practice or certification for a particular profession or occupation shall not by itself be considered sufficient evidence of such exceptional ability."],[0,"(3) Skilled workers, professionals, and other workers"],[0,"(A) In general"],[2,"Visas shall be made available, in a number not to exceed 28.6 percent of such worldwide level, plus any visas not required for the classes specified in paragraphs (1) and (2), to the following classes of aliens who are not described in paragraph (2):"],[0,"(i) Skilled workers"],[3,"Qualified immigrants who are capable, at the time of petitioning for classification under this paragraph, of performing skilled labor (requiring at least 2 years training or experience), not of a temporary or seasonal nature, for which qualified workers are not available in the United States."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1153?type=usc&year=mostrecent&link-type=html"},"head":"§1153. Allocation of immigrant visas","tname":"Aliens and Nationality","by":{"0":"57","1":"6, 37, 25, 47"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"12, 32, 56, 32, 56","1":"24"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","subs":["(1)"],"by":{"0":"32, 56, 32, 56"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","by":{"0":"32, 56"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"0":"32, 56"}},{"t":"usc","label":"8 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/8/1104","by":{"0":"50"}},{"t":"usc","label":"8 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/8/1152","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(1)(B)"],"stext":{"head":"§1152. Numerical limitations on individual foreign states","paras":[[0,"(a) Per country level"],[0,"(1) Nondiscrimination"],[1,"(A) Except as specifically provided in paragraph (2) and in sections 1101(a)(27), 1151(b)(2)(A)(i), and 1153 of this title, no person shall receive any preference or priority or be discriminated against in the issuance of an immigrant visa because of the person's race, sex, nationality, place of birth, or place of residence."],[1,"(B) Nothing in this paragraph shall be construed to limit the authority of the Secretary of State to determine the procedures for the processing of immigrant visa applications or the locations where such applications will be processed."],[0,"(2) Per country levels for family-sponsored and employment-based immigrants"],[1,"Subject to paragraphs (3), (4), and (5), the total number of immigrant visas made available to natives of any single foreign state or dependent area under subsections (a) and (b) of section 1153 of this title in any fiscal year may not exceed 7 percent (in the case of a single foreign state) or 2 percent (in the case of a dependent area) of the total number of such visas made available under such subsections in that fiscal year."],[0,"(3) Exception if additional visas available"],[1,"If because of the application of paragraph (2) with respect to one or more foreign states or dependent areas, the total number of visas available under both subsections (a) and (b) of section 1153 of this title for a calendar quarter exceeds the number of qualified immigrants who otherwise may be issued such a visa, paragraph (2) shall not apply to visas made available to such states or areas during the remainder of such calendar quarter."],[0,"(4) Special rules for spouses and children of lawful permanent resident aliens"],[0,"(A) 75 percent of 2nd preference set-aside for spouses and children not subject to per country limitation"],[0,"(i) In general"],[3,"Of the visa numbers made available under section 1153(a) of this title to immigrants described in section 1153(a)(2)(A) of this title in any fiscal year, 75 percent of the 2–A floor (as defined in clause (ii)) shall be issued without regard to the numerical limitation under paragraph (2)."],[0,"(ii) \"2–A floor\" defined"],[3,"In this paragraph, the term \"2–A floor\" means, for a fiscal year, 77 percent of the total number of visas made available under section 1153(a) of this title to immigrants described in section 1153(a)(2) of this title in the fiscal year."],[0,"(B) Treatment of remaining 25 percent for countries subject to subsection (e)"],[0,"(i) In general"],[3,"Of the visa numbers made available under section 1153(a) of this title to immigrants described in section 1153(a)(2)(A) of this title in any fiscal year, the remaining 25 percent of the 2–A floor shall be available in the case of a state or area that is subject to subsection (e) only to the extent that the total number of visas issued in accordance with subparagraph (A) to natives of the foreign state or area is less than the subsection (e) ceiling (as defined in clause (ii))."],[0,"(ii) \"Subsection (e) ceiling\" defined"],[3,"In clause (i), the term \"subsection (e) ceiling\" means, for a foreign state or dependent area, 77 percent of the maximum number of visas that may be made available under section 1153(a) of this title to immigrants who are natives of the state or area under section 1153(a)(2) of this title consistent with subsection (e)."],[0,"(C) Treatment of unmarried sons and daughters in countries subject to subsection (e)"],[2,"In the case of a foreign state or dependent area to which subsection (e) applies, the number of immigrant visas that may be made available to natives of the state or area under section 1153(a)(2)(B) of this title may not exceed—"],[3,"(i) 23 percent of the maximum number of visas that may be made available under section 1153(a) of this title to immigrants of the state or area described in section 1153(a)(2) of this title consistent with subsection (e), or"],[3,"(ii) the number (if any) by which the maximum number of visas that may be made available under section 1153(a) of this title to immigrants of the state or area described in section 1153(a)(2) of this title consistent with subsection (e) exceeds the number of visas issued under section 1153(a)(2)(A) of this title,"],[2,"whichever is greater."],[0,"(D) Limiting pass down for certain countries subject to subsection (e)"],[2,"In the case of a foreign state or dependent area to which subsection (e) applies, if the total number of visas issued under section 1153(a)(2) of this title exceeds the maximum number of visas that may be made available to immigrants of the state or area under section 1153(a)(2) of this title consistent with subsection (e) (determined without regard to this paragraph), in applying paragraphs (3) and (4) of section 1153(a) of this title under subsection (e)(2) all visas shall be deemed to have been required for the classes specified in paragraphs (1) and (2) of such section."],[0,"(5) Rules for employment-based immigrants"],[0,"(A) Employment-based immigrants not subject to per country limitation if additional visas available"],[2,"If the total number of visas available under paragraph (1), (2), (3), (4), or (5) of section 1153(b) of this title for a calendar quarter exceeds the number of qualified immigrants who may otherwise be issued such visas, the visas made available under that paragraph shall be issued without regard to the numerical limitation under paragraph (2) of this subsection during the remainder of the calendar quarter."],[0,"(B) Limiting fall across for certain countries subject to subsection (e)"],[2,"In the case of a foreign state or dependent area to which subsection (e) applies, if the total number of visas issued under section 1153(b) of this title exceeds the maximum number of visas that may be made available to immigrants of the state or area under section 1153(b) of this title consistent with subsection (e) (determined without regard to this paragraph), in applying subsection (e) all visas shall be deemed to have been required for the classes of aliens specified in section 1153(b) of this title."],[0,"(b) Rules for chargeability"],[0,"Each independent country, self-governing dominion, mandated territory, and territory under the international trusteeship system of the United Nations, other than the United States and its outlying possessions, shall be treated as a separate foreign state for the purposes of a numerical level established under subsection (a)(2) when approved by the Secretary of State. All other inhabited lands shall be attributed to a foreign state specified by the Secretary of State. For the purposes of this chapter the foreign state to which an immigrant is chargeable shall be determined by birth within such foreign state except that (1) an alien child, when accompanied by or following to join his alien parent or parents, may be charged to the foreign state of either parent if such parent has received or would be qualified for an immigrant visa, if necessary to prevent the separation of the child from the parent or parents, and if immigration charged to the foreign state to which such parent has been or would be chargeable has not reached a numerical level established under subsection (a)(2) for that fiscal year; (2) if an alien is chargeable to a different foreign state from that of his spouse, the foreign state to which such alien is chargeable may, if necessary to prevent the separation of husband and wife, be determined by the foreign state of the spouse he is accompanying or following to join, if such spouse has received or would be qualified for an immigrant visa and if immigration charged to the foreign state to which such spouse has been or would be chargeable has not reached a numerical level established under subsection (a)(2) for that fiscal year; (3) an alien born in the United States shall be considered as having been born in the country of which he is a citizen or subject, or, if he is not a citizen or subject of any country, in the last foreign country in which he had his residence as determined by the consular officer; and (4) an alien born within any foreign state in which neither of his parents was born and in which neither of his parents had a residence at the time of such alien's birth may be charged to the foreign state of either parent."],[0,"(c) Chargeability for dependent areas"],[0,"Any immigrant born in a colony or other component or dependent area of a foreign state overseas from the foreign state, other than an alien described in section 1151(b) of this title, shall be chargeable for the purpose of the limitation set forth in subsection (a), to the foreign state."],[0,"(d) Changes in territory"],[0,"In the case of any change in the territorial limits of foreign states, the Secretary of State shall, upon recognition of such change issue appropriate instructions to all diplomatic and consular offices."],[0,"(e) Special rules for countries at ceiling"],[0,"If it is determined that the total number of immigrant visas made available under subsections (a) and (b) of section 1153 of this title to natives of any single foreign state or dependent area will exceed the numerical limitation specified in subsection (a)(2) in any fiscal year, in determining the allotment of immigrant visa numbers to natives under subsections (a) and (b) of section 1153 of this title, visa numbers with respect to natives of that state or area shall be allocated (to the extent practicable and otherwise consistent with this section and section 1153 of this title) in a manner so that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1152?type=usc&year=mostrecent&link-type=html"},"head":"§1152. Numerical limitations on individual foreign states","tname":"Aliens and Nationality","by":{"0":"3, 3, 3, 3","2":"18, 17, 18, 19, 20, 21"}},{"t":"usc","label":"8 U.S.C. § 1181","url":"https://www.law.cornell.edu/uscode/text/8/1181","by":{"0":"3"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(a)(3)(B)","(a)(3)(C)(i)","(a)(7)(A)(i)","(a)(7)(B)(i)(II)","(a)(7)(B)(iv)","(a)(3)","(a)(6)","(a)(9)","(a)(10)","(a)(1)","(a)(2)","(b)(1)(B)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"3, 3, 3, 3, 3, 3, 3, 3","1":"6, 37, passim, 41, 36, 47, 36","2":"17, 18, 12, 12, 12, 12, 13, passim"}},{"t":"usc","label":"8 U.S.C. § 1185","url":"https://www.law.cornell.edu/uscode/text/8/1185","subs":["(a)","(a)(1)","(d)"],"stext":{"head":"§1185. Travel control of citizens and aliens","paras":[[0,"(a) Restrictions and prohibitions"],[0,"Unless otherwise ordered by the President, it shall be unlawful—"],[1,"(1) for any alien to depart from or enter or attempt to depart from or enter the United States except under such reasonable rules, regulations, and orders, and subject to such limitations and exceptions as the President may prescribe;"],[1,"(2) for any person to transport or attempt to transport from or into the United States another person with knowledge or reasonable cause to believe that the departure or entry of such other person is forbidden by this section;"],[1,"(3) for any person knowingly to make any false statement in an application for permission to depart from or enter the United States with intent to induce or secure the granting of such permission either for himself or for another;"],[1,"(4) for any person knowingly to furnish or attempt to furnish or assist in furnishing to another a permit or evidence of permission to depart or enter not issued and designed for such other person's use;"],[1,"(5) for any person knowingly to use or attempt to use any permit or evidence of permission to depart or enter not issued and designed for his use;"],[1,"(6) for any person to forge, counterfeit, mutilate, or alter, or cause or procure to be forged, counterfeited, mutilated, or altered, any permit or evidence of permission to depart from or enter the United States;"],[1,"(7) for any person knowingly to use or attempt to use or furnish to another for use any false, forged, counterfeited, mutilated, or altered permit, or evidence of permission, or any permit or evidence of permission which, though originally valid, has become or been made void or invalid."],[0,"(b) Citizens"],[0,"Except as otherwise provided by the President and subject to such limitations and exceptions as the President may authorize and prescribe, it shall be unlawful for any citizen of the United States to depart from or enter, or attempt to depart from or enter, the United States unless he bears a valid United States passport."],[0,"(c) Definitions"],[0,"The term \"United States\" as used in this section includes the Canal Zone, and all territory and waters, continental or insular, subject to the jurisdiction of the United States. The term \"person\" as used in this section shall be deemed to mean any individual, partnership, association, company, or other incorporated body of individuals, or corporation, or body politic."],[0,"(d) Nonadmission of certain aliens"],[0,"Nothing in this section shall be construed to entitle an alien to whom a permit to enter the United States has been issued to enter the United States, if, upon arrival in the United States, he is found to be inadmissible under any of the provisions of this chapter, or any other law, relative to the entry of aliens into the United States."],[0,"(e) Revocation of proclamation as affecting penalties"],[0,"The revocation of any rule, regulation, or order issued in pursuance of this section shall not prevent prosecution for any offense committed, or the imposition of any penalties or forfeitures, liability for which was incurred under this section prior to the revocation of such rule, regulation, or order."],[0,"(f) Permits to enter"],[0,"Passports, visas, reentry permits, and other documents required for entry under this chapter may be considered as permits to enter for the purposes of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1185?type=usc&year=mostrecent&link-type=html"},"head":"§1185. Travel control of citizens and aliens","tname":"Aliens and Nationality","by":{"0":"3, 3, 3","1":"passim, passim","2":"9, passim"}},{"t":"usc","label":"8 U.S.C. § 1187","url":"https://www.law.cornell.edu/uscode/text/8/1187","subs":["(a)(12)","(a)(12)(A)(i)","(a)(12)(A)(ii)","(a)(12)(D)(i)","(a)(12)(D)(ii)"],"stext":{"head":"§1187. Visa waiver program for certain visitors","paras":[[0,"(a) Establishment of program"],[0,"The Secretary of Homeland Security and the Secretary of State are authorized to establish a program (hereinafter in this section referred to as the \"program\") under which the requirement of paragraph (7)(B)(i)(II) of section 1182(a) of this title may be waived by the Secretary of Homeland Security, in consultation with the Secretary of State and in accordance with this section, in the case of an alien who meets the following requirements:"],[0,"(1) Seeking entry as tourist for 90 days or less"],[1,"The alien is applying for admission during the program as a nonimmigrant visitor (described in section 1101(a)(15)(B) of this title) for a period not exceeding 90 days."],[0,"(2) National of program country"],[1,"The alien is a national of, and presents a passport issued by, a country which—"],[2,"(A) extends (or agrees to extend), either on its own or in conjunction with one or more other countries that are described in subparagraph (B) and that have established with it a common area for immigration admissions, reciprocal privileges to citizens and nationals of the United States, and"],[2,"(B) is designated as a pilot program country under subsection (c)."],[0,"(3) Passport requirements"],[1,"The alien, at the time of application for admission, is in possession of a valid unexpired passport that satisfies the following:"],[0,"(A) Machine readable"],[2,"The passport is a machine-readable passport that is tamper-resistant, incorporates document authentication identifiers, and otherwise satisfies the internationally accepted standard for machine readability."],[0,"(B) Electronic"],[2,"Beginning on April 1, 2016, the passport is an electronic passport that is fraud-resistant, contains relevant biographic and biometric information (as determined by the Secretary of Homeland Security), and otherwise satisfies internationally accepted standards for electronic passports."],[0,"(4) Executes immigration forms"],[1,"The alien before the time of such admission completes such immigration form as the Secretary of Homeland Security shall establish."],[0,"(5) Entry into the United States"],[1,"If arriving by sea or air, the alien arrives at the port of entry into the United States on a carrier, including any carrier conducting operations under part 135 of title 14, Code of Federal Regulations, or a noncommercial aircraft that is owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations 1 which has entered into an agreement with the Secretary of Homeland Security pursuant to subsection (e). The Secretary of Homeland Security is authorized to require a carrier conducting operations under part 135 of title 14, Code of Federal Regulations, or a domestic corporation conducting operations under part 91 of that title, to give suitable and proper bond, in such reasonable amount and containing such conditions as the Secretary of Homeland Security may deem sufficient to ensure compliance with the indemnification requirements of this section, as a term of such an agreement."],[0,"(6) Not a safety threat"],[1,"The alien has been determined not to represent a threat to the welfare, health, safety, or security of the United States."],[0,"(7) No previous violation"],[1,"If the alien previously was admitted without a visa under this section, the alien must not have failed to comply with the conditions of any previous admission as such a nonimmigrant."],[0,"(8) Round-trip ticket"],[1,"The alien is in possession of a round-trip transportation ticket (unless this requirement is waived by the Secretary of Homeland Security under regulations or the alien is arriving at the port of entry on an aircraft operated under part 135 of title 14, Code of Federal Regulations, or a noncommercial aircraft that is owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations)."],[0,"(9) Automated system check"],[1,"The identity of the alien has been checked using an automated electronic database containing information about the inadmissibility of aliens to uncover any grounds on which the alien may be inadmissible to the United States, and no such ground has been found."],[0,"(10) Electronic transmission of identification information"],[1,"Operators of aircraft under part 135 of title 14, Code of Federal Regulations, or operators of noncommercial aircraft that are owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations, carrying any alien passenger who will apply for admission under this section shall furnish such information as the Secretary of Homeland Security by regulation shall prescribe as necessary for the identification of any alien passenger being transported and for the enforcement of the immigration laws. Such information shall be electronically transmitted not less than one hour prior to arrival at the port of entry for purposes of checking for inadmissibility using the automated electronic database."],[0,"(11) Eligibility determination under the electronic system for travel authorization"],[1,"Beginning on the date on which the electronic system for travel authorization developed under subsection (h)(3) is fully operational, each alien traveling under the program shall, before applying for admission to the United States, electronically provide to the system biographical information and such other information as the Secretary of Homeland Security shall determine necessary to determine the eligibility of, and whether there exists a law enforcement or security risk in permitting, the alien to travel to the United States. Upon review of such biographical information, the Secretary of Homeland Security shall determine whether the alien is eligible to travel to the United States under the program."],[0,"(12) Not present in Iraq, Syria, or any other country or area of concern"],[0,"(A) In general"],[2,"Except as provided in subparagraphs (B) and (C)—"],[3,"(i) the alien has not been present, at any time on or after March 1, 2011—"],[4,"(I) in Iraq or Syria;"],[4,"(II) in a country that is designated by the Secretary of State under section 4605(j) 2 of title 50 (as continued in effect under the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.)), section 2780 of title 22, section 2371 of title 22, or any other provision of law, as a country, the government of which has repeatedly provided support of acts of international terrorism; or"],[4,"(III) in any other country or area of concern designated by the Secretary of Homeland Security under subparagraph (D); and"],[3,"(ii) regardless of whether the alien is a national of a program country, the alien is not a national of—"],[4,"(I) Iraq or Syria;"],[4,"(II) a country that is designated, at the time the alien applies for admission, by the Secretary of State under section 4605(j) 2 of title 50 (as continued in effect under the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.)), section 2780 of title 22, section 2371 of title 22, or any other provision of law, as a country, the government of which has repeatedly provided support of acts of international terrorism; or"],[4,"(III) any other country that is designated, at the time the alien applies for admission, by the Secretary of Homeland Security under subparagraph (D)."],[0,"(B) Certain military personnel and government employees"],[2,"Subparagraph (A)(i) shall not apply in the case of an alien if the Secretary of Homeland Security determines that the alien was present—"],[3,"(i) in order to perform military service in the armed forces of a program country; or"],[3,"(ii) in order to carry out official duties as a full time employee of the government of a program country."],[0,"(C) Waiver"],[2,"The Secretary of Homeland Security may waive the application of subparagraph (A) to an alien if the Secretary determines that such a waiver is in the law enforcement or national security interests of the United States."],[0,"(D) Countries or areas of concern"],[0,"(i) In general"],[3,"Not later than 60 days after December 18, 2015, the Secretary of Homeland Security, in consultation with the Secretary of State and the Director of National Intelligence, shall determine whether the requirement under subparagraph (A) shall apply to any other country or area."],[0,"(ii) Criteria"],[3,"In making a determination under clause (i), the Secretary shall consider—"],[4,"(I) whether the presence of an alien in the country or area increases the likelihood that the alien is a credible threat to the national security of the United States;"],[4,"(II) whether a foreign terrorist organization has a significant presence in the country or area; and"],[4,"(III) whether the country or area is a safe haven for terrorists."],[0,"(iii) Annual review"],[3,"The Secretary shall conduct a review, on an annual basis, of any determination made under clause (i)."],[0,"(E) Report"],[2,"Beginning not later than one year after December 18, 2015, and annually thereafter, the Secretary of Homeland Security shall submit to the Committee on Homeland Security, the Committee on Foreign Affairs, the Permanent Select Committee on Intelligence, and the Committee on the Judiciary of the House of Representatives, and the Committee on Homeland Security and Governmental Affairs, the Committee on Foreign Relations, the Select Committee on Intelligence, and the Committee on the Judiciary of the Senate a report on each instance in which the Secretary exercised the waiver authority under subparagraph (C) during the previous year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1187?type=usc&year=mostrecent&link-type=html"},"head":"§1187. Visa waiver program for certain visitors","tname":"Aliens and Nationality","by":{"0":"3, 3, 3, 3, 3, 3","2":"15, 15"}},{"t":"usc","label":"8 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/8/1201","subs":["(a)(1)","(g)","(h)","(g)(1)","(a)"],"stext":{"head":"§1201. Issuance of visas","paras":[[0,"(a) Immigrants; nonimmigrants"],[0,"(1) Under the conditions hereinafter prescribed and subject to the limitations prescribed in this chapter or regulations issued thereunder, a consular officer may issue"],[1,"(A) to an immigrant who has made proper application therefor, an immigrant visa which shall consist of the application provided for in section 1202 of this title, visaed by such consular officer, and shall specify the foreign state, if any, to which the immigrant is charged, the immigrant's particular status under such foreign state, the preference, immediate relative, or special immigrant classification to which the alien is charged, the date on which the validity of the visa shall expire, and such additional information as may be required; and"],[1,"(B) to a nonimmigrant who has made proper application therefor, a nonimmigrant visa, which shall specify the classification under section 1101(a)(15) of this title of the nonimmigrant, the period during which the nonimmigrant visa shall be valid, and such additional information as may be required."],[0,"(2) The Secretary of State shall provide to the Service an electronic version of the visa file of each alien who has been issued a visa to ensure that the data in that visa file is available to immigration inspectors at the United States ports of entry before the arrival of the alien at such a port of entry."],[0,"(b) Registration; photographs; waiver of requirement"],[0,"Each alien who applies for a visa shall be registered in connection with his application, and shall furnish copies of his photograph signed by him for such use as may be by regulations required. The requirements of this subsection may be waived in the discretion of the Secretary of State in the case of any alien who is within that class of nonimmigrants enumerated in sections 1101(a)(15)(A), and 1101(a)(15)(G) of this title, or in the case of any alien who is granted a diplomatic visa on a diplomatic passport or on the equivalent thereof."],[0,"(c) Period of validity; renewal or replacement"],[0,"(1) Immigrant visas"],[1,"An immigrant visa shall be valid for such period, not exceeding six months, as shall be by regulations prescribed, except that any visa issued to a child lawfully adopted by a United States citizen and spouse while such citizen is serving abroad in the United States Armed Forces, or is employed abroad by the United States Government, or is temporarily abroad on business, shall be valid until such time, for a period not to exceed three years, as the adoptive citizen parent returns to the United States in due course of his service, employment, or business."],[0,"(2) Nonimmigrant visas"],[1,"A nonimmigrant visa shall be valid for such periods as shall be by regulations prescribed. In prescribing the period of validity of a nonimmigrant visa in the case of nationals of any foreign country who are eligible for such visas, the Secretary of State shall, insofar as practicable, accord to such nationals the same treatment upon a reciprocal basis as such foreign country accords to nationals of the United States who are within a similar class; except that in the case of aliens who are nationals of a foreign country and who either are granted refugee status and firmly resettled in another foreign country or are granted permanent residence and residing in another foreign country, the Secretary of State may prescribe the period of validity of such a visa based upon the treatment granted by that other foreign country to alien refugees and permanent residents, respectively, in the United States."],[0,"(3) Visa replacement"],[1,"An immigrant visa may be replaced under the original number during the fiscal year in which the original visa was issued for an immigrant who establishes to the satisfaction of the consular officer that the immigrant—"],[2,"(A) was unable to use the original immigrant visa during the period of its validity because of reasons beyond his control and for which he was not responsible;"],[2,"(B) is found by a consular officer to be eligible for an immigrant visa; and"],[2,"(C) pays again the statutory fees for an application and an immigrant visa."],[0,"(4) Fee waiver"],[1,"If an immigrant visa was issued, on or after March 27, 2013, for a child who has been lawfully adopted, or who is coming to the United States to be adopted, by a United States citizen, any statutory immigrant visa fees relating to a renewal or replacement of such visa may be waived or, if already paid, may be refunded upon request, subject to such criteria as the Secretary of State may prescribe, if—"],[2,"(A) the immigrant child was unable to use the original immigrant visa during the period of its validity as a direct result of extraordinary circumstances, including the denial of an exit permit; and"],[2,"(B) if such inability was attributable to factors beyond the control of the adopting parent or parents and of the immigrant."],[0,"(d) Physical examination"],[0,"Prior to the issuance of an immigrant visa to any alien, the consular officer shall require such alien to submit to a physical and mental examination in accordance with such regulations as may be prescribed. Prior to the issuance of a nonimmigrant visa to any alien, the consular officer may require such alien to submit to a physical or mental examination, or both, if in his opinion such examination is necessary to ascertain whether such alien is eligible to receive a visa."],[0,"(e) Surrender of visa"],[0,"Each immigrant shall surrender his immigrant visa to the immigration officer at the port of entry, who shall endorse on the visa the date and the port of arrival, the identity of the vessel or other means of transportation by which the immigrant arrived, and such other endorsements as may be by regulations required."],[0,"(f) Surrender of documents"],[0,"Each nonimmigrant shall present or surrender to the immigration officer at the port of entry such documents as may be by regulation required. In the case of an alien crewman not in possession of any individual documents other than a passport and until such time as it becomes practicable to issue individual documents, such alien crewman may be admitted, subject to the provisions of this part, if his name appears in the crew list of the vessel or aircraft on which he arrives and the crew list is visaed by a consular officer, but the consular officer shall have the right to deny admission to any alien crewman from the crew list visa."],[0,"(g) Nonissuance of visas or other documents"],[0,"No visa or other documentation shall be issued to an alien if (1) it appears to the consular officer, from statements in the application, or in the papers submitted therewith, that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law, (2) the application fails to comply with the provisions of this chapter, or the regulations issued thereunder, or (3) the consular officer knows or has reason to believe that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law: Provided, That a visa or other documentation may be issued to an alien who is within the purview of section 1182(a)(4) of this title, if such alien is otherwise entitled to receive a visa or other documentation, upon receipt of notice by the consular officer from the Attorney General of the giving of a bond or undertaking providing indemnity as in the case of aliens admitted under section 1183 of this title: Provided further, That a visa may be issued to an alien defined in section 1101(a)(15)(B) or (F) of this title, if such alien is otherwise entitled to receive a visa, upon receipt of a notice by the consular officer from the Attorney General of the giving of a bond with sufficient surety in such sum and containing such conditions as the consular officer shall prescribe, to insure that at the expiration of the time for which such alien has been admitted by the Attorney General, as provided in section 1184(a) of this title, or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States."],[0,"(h) Nonadmission upon arrival"],[0,"Nothing in this chapter shall be construed to entitle any alien, to whom a visa or other documentation has been issued, to be admitted 1 the United States, if, upon arrival at a port of entry in the United States, he is found to be inadmissible under this chapter, or any other provision of law. The substance of this subsection shall appear upon every visa application."],[0,"(i) Revocation of visas or documents"],[0,"After the issuance of a visa or other documentation to any alien, the consular officer or the Secretary of State may at any time, in his discretion, revoke such visa or other documentation. Notice of such revocation shall be communicated to the Attorney General, and such revocation shall invalidate the visa or other documentation from the date of issuance: Provided, That carriers or transportation companies, and masters, commanding officers, agents, owners, charterers, or consignees, shall not be penalized under section 1323(b) of this title for action taken in reliance on such visas or other documentation, unless they received due notice of such revocation prior to the alien's embarkation. There shall be no means of judicial review (including review pursuant to section 2241 of title 28 or any other habeas corpus provision, and sections 1361 and 1651 of such title) of a revocation under this subsection, except in the context of a removal proceeding if such revocation provides the sole ground for removal under section 1227(a)(1)(B) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1201?type=usc&year=mostrecent&link-type=html"},"head":"§1201. Issuance of visas","tname":"Aliens and Nationality","by":{"0":"3, 3, 3, 3","1":"37, 5","2":"18, 18, 19, 18, 19"}},{"t":"usc","label":"8 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/8/1202","subs":["(h)","(h)(2)(F)(i)"],"stext":{"head":"§1202. Application for visas","paras":[[0,"(a) Immigrant visas"],[0,"Every alien applying for an immigrant visa and for alien registration shall make application therefor in such form and manner and at such place as shall be by regulations prescribed. In the application the alien shall state his full and true name, and any other name which he has used or by which he has been known; age and sex; the date and place of his birth; and such additional information necessary to the identification of the applicant and the enforcement of the immigration and nationality laws as may be by regulations prescribed."],[0,"(b) Other documentary evidence for immigrant visa"],[0,"Every alien applying for an immigrant visa shall present a valid unexpired passport or other suitable travel document, or document of identity and nationality, if such document is required under the regulations issued by the Secretary of State. The immigrant shall furnish to the consular officer with his application a copy of a certification by the appropriate police authorities stating what their records show concerning the immigrant; a certified copy of any existing prison record, military record, and record of his birth; and a certified copy of all other records or documents concerning him or his case which may be required by the consular officer. The copy of each document so furnished shall be permanently attached to the application and become a part thereof. In the event that the immigrant establishes to the satisfaction of the consular officer that any document or record required by this subsection is unobtainable, the consular officer may permit the immigrant to submit in lieu of such document or record other satisfactory evidence of the fact to which such document or record would, if obtainable, pertain. All immigrant visa applications shall be reviewed and adjudicated by a consular officer."],[0,"(c) Nonimmigrant visas; nonimmigrant registration; form, manner and contents of application"],[0,"Every alien applying for a nonimmigrant visa and for alien registration shall make application therefor in such form and manner as shall be by regulations prescribed. In the application the alien shall state his full and true name, the date and place of birth, his nationality, the purpose and length of his intended stay in the United States; his marital status; and such additional information necessary to the identification of the applicant, the determination of his eligibility for a nonimmigrant visa, and the enforcement of the immigration and nationality laws as may be by regulations prescribed. The alien shall provide complete and accurate information in response to any request for information contained in the application. At the discretion of the Secretary of State, application forms for the various classes of nonimmigrant admissions described in section 1101(a)(15) of this title may vary according to the class of visa being requested."],[0,"(d) Other documentary evidence for nonimmigrant visa"],[0,"Every alien applying for a nonimmigrant visa and alien registration shall furnish to the consular officer, with his application, a certified copy of such documents pertaining to him as may be by regulations required. All nonimmigrant visa applications shall be reviewed and adjudicated by a consular officer."],[0,"(e) Signing and verification of application"],[0,"Except as may be otherwise prescribed by regulations, each application for an immigrant visa shall be signed by the applicant in the presence of the consular officer, and verified by the oath of the applicant administered by the consular officer. The application for an immigrant visa, when visaed by the consular officer, shall become the immigrant visa. The application for a nonimmigrant visa or other documentation as a nonimmigrant shall be disposed of as may be by regulations prescribed. The issuance of a nonimmigrant visa shall, except as may be otherwise by regulations prescribed, be evidenced by a stamp, or other 1 placed in the alien's passport."],[0,"(f) Confidential nature of records"],[0,"The records of the Department of State and of diplomatic and consular offices of the United States pertaining to the issuance or refusal of visas or permits to enter the United States shall be considered confidential and shall be used only for the formulation, amendment, administration, or enforcement of the immigration, nationality, and other laws of the United States, except that—"],[1,"(1) in the discretion of the Secretary of State certified copies of such records may be made available to a court which certifies that the information contained in such records is needed by the court in the interest of the ends of justice in a case pending before the court.2"],[1,"(2) the Secretary of State, in the Secretary's discretion and on the basis of reciprocity, may provide to a foreign government information in the Department of State's computerized visa lookout database and, when necessary and appropriate, other records covered by this section related to information in the database—"],[2,"(A) with regard to individual aliens, at any time on a case-by-case basis for the purpose of preventing, investigating, or punishing acts that would constitute a crime in the United States, including, but not limited to, terrorism or trafficking in controlled substances, persons, or illicit weapons; or"],[2,"(B) with regard to any or all aliens in the database, pursuant to such conditions as the Secretary of State shall establish in an agreement with the foreign government in which that government agrees to use such information and records for the purposes described in subparagraph (A) or to deny visas to persons who would be inadmissible to the United States."],[0,"(g) Nonimmigrant visa void at conclusion of authorized period of stay"],[0,"(1) In the case of an alien who has been admitted on the basis of a nonimmigrant visa and remained in the United States beyond the period of stay authorized by the Attorney General, such visa shall be void beginning after the conclusion of such period of stay."],[0,"(2) An alien described in paragraph (1) shall be ineligible to be readmitted to the United States as a nonimmigrant, except—"],[1,"(A) on the basis of a visa (other than the visa described in paragraph (1)) issued in a consular office located in the country of the alien's nationality (or, if there is no office in such country, in such other consular office as the Secretary of State shall specify); or"],[1,"(B) where extraordinary circumstances are found by the Secretary of State to exist."],[0,"(h) In person interview with consular officer"],[0,"Notwithstanding any other provision of this chapter, the Secretary of State shall require every alien applying for a nonimmigrant visa—"],[1,"(1) who is at least 14 years of age and not more than 79 years of age to submit to an in person interview with a consular officer unless the requirement for such interview is waived—"],[2,"(A) by a consular official and such alien is—"],[3,"(i) within that class of nonimmigrants enumerated in subparagraph (A) or (G) of section 1101(a)(15) of this title;"],[3,"(ii) within the NATO visa category;"],[3,"(iii) within that class of nonimmigrants enumerated in section 1101(a)(15)(C)(iii) 3 of this title (referred to as the \"C–3 visa\" category); or"],[3,"(iv) granted a diplomatic or official visa on a diplomatic or official passport or on the equivalent thereof;"],[2,"(B) by a consular official and such alien is applying for a visa—"],[3,"(i) not more than 12 months after the date on which such alien's prior visa expired;"],[3,"(ii) for the visa classification for which such prior visa was issued;"],[3,"(iii) from the consular post located in the country of such alien's usual residence, unless otherwise prescribed in regulations that require an applicant to apply for a visa in the country of which such applicant is a national; and"],[3,"(iv) the consular officer has no indication that such alien has not complied with the immigration laws and regulations of the United States; or"],[2,"(C) by the Secretary of State if the Secretary determines that such waiver is—"],[3,"(i) in the national interest of the United States; or"],[3,"(ii) necessary as a result of unusual or emergent circumstances; and"],[1,"(2) notwithstanding paragraph (1), to submit to an in person interview with a consular officer if such alien—"],[2,"(A) is not a national or resident of the country in which such alien is applying for a visa;"],[2,"(B) was previously refused a visa, unless such refusal was overcome or a waiver of ineligibility has been obtained;"],[2,"(C) is listed in the Consular Lookout and Support System (or successor system at the Department of State);"],[2,"(D) is a national of a country officially designated by the Secretary of State as a state sponsor of terrorism, except such nationals who possess nationalities of countries that are not designated as state sponsors of terrorism;"],[2,"(E) requires a security advisory opinion or other Department of State clearance, unless such alien is—"],[3,"(i) within that class of nonimmigrants enumerated in subparagraph (A) or (G) of section 1101(a)(15) of this title;"],[3,"(ii) within the NATO visa category;"],[3,"(iii) within that class of nonimmigrants enumerated in section 1101(a)(15)(C)(iii) 3 of this title (referred to as the \"C–3 visa\" category); or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1202?type=usc&year=mostrecent&link-type=html"},"head":"§1202. Application for visas","tname":"Aliens and Nationality","by":{"0":"3","1":"5, 37, 43, 48","2":"14"}},{"t":"usc","label":"8 U.S.C. § 1203","url":"https://www.law.cornell.edu/uscode/text/8/1203","by":{"0":"3"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(a)"],"by":{"0":"20"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"20, 19","2":"2"}},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(d)"],"stext":{"head":"§1253. Penalties related to removal","paras":[[0,"(a) Penalty for failure to depart"],[0,"(1) In general"],[1,"Any alien against whom a final order of removal is outstanding by reason of being a member of any of the classes described in section 1227(a) of this title, who—"],[2,"(A) willfully fails or refuses to depart from the United States within a period of 90 days from the date of the final order of removal under administrative processes, or if judicial review is had, then from the date of the final order of the court,"],[2,"(B) willfully fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure,"],[2,"(C) connives or conspires, or takes any other action, designed to prevent or hamper or with the purpose of preventing or hampering the alien's departure pursuant to such, or"],[2,"(D) willfully fails or refuses to present himself or herself for removal at the time and place required by the Attorney General pursuant to such order,"],[1,"shall be fined under title 18, or imprisoned not more than four years (or 10 years if the alien is a member of any of the classes described in paragraph (1)(E), (2), (3), or (4) of section 1227(a) of this title), or both."],[0,"(2) Exception"],[1,"It is not a violation of paragraph (1) to take any proper steps for the purpose of securing cancellation of or exemption from such order of removal or for the purpose of securing the alien's release from incarceration or custody."],[0,"(3) Suspension"],[1,"The court may for good cause suspend the sentence of an alien under this subsection and order the alien's release under such conditions as the court may prescribe. In determining whether good cause has been shown to justify releasing the alien, the court shall take into account such factors as—"],[2,"(A) the age, health, and period of detention of the alien;"],[2,"(B) the effect of the alien's release upon the national security and public peace or safety;"],[2,"(C) the likelihood of the alien's resuming or following a course of conduct which made or would make the alien deportable;"],[2,"(D) the character of the efforts made by such alien himself and by representatives of the country or countries to which the alien's removal is directed to expedite the alien's departure from the United States;"],[2,"(E) the reason for the inability of the Government of the United States to secure passports, other travel documents, or removal facilities from the country or countries to which the alien has been ordered removed; and"],[2,"(F) the eligibility of the alien for discretionary relief under the immigration laws."],[0,"(b) Willful failure to comply with terms of release under supervision"],[0,"An alien who shall willfully fail to comply with regulations or requirements issued pursuant to section 1231(a)(3) of this title or knowingly give false information in response to an inquiry under such section shall be fined not more than $1,000 or imprisoned for not more than one year, or both."],[0,"(c) Penalties relating to vessels and aircraft"],[0,"(1) Civil penalties"],[0,"(A) Failure to carry out certain orders"],[2,"If the Attorney General is satisfied that a person has violated subsection (d) or (e) of section 1231 of this title, the person shall pay to the Commissioner the sum of $2,000 for each violation."],[0,"(B) Failure to remove alien stowaways"],[2,"If the Attorney General is satisfied that a person has failed to remove an alien stowaway as required under section 1231(d)(2) of this title, the person shall pay to the Commissioner the sum of $5,000 for each alien stowaway not removed."],[0,"(C) No compromise"],[2,"The Attorney General may not compromise the amount of such penalty under this paragraph."],[0,"(2) Clearing vessels and aircraft"],[0,"(A) Clearance before decision on liability"],[2,"A vessel or aircraft may be granted clearance before a decision on liability is made under paragraph (1) only if a bond approved by the Attorney General or an amount sufficient to pay the civil penalty is deposited with the Commissioner."],[0,"(B) Prohibition on clearance while penalty unpaid"],[2,"A vessel or aircraft may not be granted clearance if a civil penalty imposed under paragraph (1) is not paid."],[0,"(d) Discontinuing granting visas to nationals of country denying or delaying accepting alien"],[0,"On being notified by the Attorney General that the government of a foreign country denies or unreasonably delays accepting an alien who is a citizen, subject, national, or resident of that country after the Attorney General asks whether the government will accept the alien under this section, the Secretary of State shall order consular officers in that foreign country to discontinue granting immigrant visas or nonimmigrant visas, or both, to citizens, subjects, nationals, and residents of that country until the Attorney General notifies the Secretary that the country has accepted the alien."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1253?type=usc&year=mostrecent&link-type=html"},"head":"§1253. Penalties related to removal","tname":"Aliens and Nationality","by":{"0":"56","2":"15, 20"}},{"t":"usc","label":"6 U.S.C. § 236","url":"https://www.law.cornell.edu/uscode/text/6/236","subs":["(b)","(c)","(c)(1)"],"by":{"0":"50, 50, 50, 37, 53, 37, 53"}},{"t":"reg","label":"6 U.S.C. 236(c)(1) .......................................................20, 5a 6 U.S.C. 236(f )..........................................., 44 Fed. Reg. 67,947","url":"https://www.govinfo.gov/link/fr/44/67947","by":{"0":"37, 53","2":"8"}},{"t":"reg","label":"Exec. Order No. 12,206, 45 Fed. Reg. 24,101","url":"https://www.govinfo.gov/link/fr/45/24101","by":{"0":"53","2":"8"}},{"t":"reg","label":"Exec. Order No. 13,712, 80 Fed. Reg. 73,633","url":"https://www.govinfo.gov/link/fr/80/73633","by":{"0":"38"}},{"t":"reg","label":"Exec. Order No. 13,769, 82 Fed. Reg. 8977","url":"https://www.govinfo.gov/link/fr/82/8977","by":{"0":"4, 5, 6"}},{"t":"reg","label":"Exec. Order No. 13,780, 82 Fed. Reg. 13,209","url":"https://www.govinfo.gov/link/fr/82/13209","by":{"0":"5","2":"25"}},{"t":"reg","label":"and rule—Continued: Exec. Order No. 13,815, 82 Fed. Reg. 50,055","url":"https://www.govinfo.gov/link/fr/82/50055","by":{"0":"6"}},{"t":"reg","label":"Proclamation No. 4865, 46 Fed. Reg. 48,107","url":"https://www.govinfo.gov/link/fr/46/48107","by":{"0":"37"}},{"t":"reg","label":"Proclamation No. 5517, 51 Fed. Reg. 30,470","url":"https://www.govinfo.gov/link/fr/51/30470","by":{"0":"43, 53","2":"8"}},{"t":"reg","label":"Proclamation No. 5829, 53 Fed. Reg. 22,289","url":"https://www.govinfo.gov/link/fr/53/22289","by":{"0":"41"}},{"t":"reg","label":"Proclamation No. 5887, 53 Fed. Reg. 43,185","url":"https://www.govinfo.gov/link/fr/53/43185","by":{"0":"38"}},{"t":"reg","label":"Proclamation No. 6749, 59 Fed. Reg. 54,119","url":"https://www.govinfo.gov/link/fr/59/54119","by":{"0":"43"}},{"t":"reg","label":"Proclamation No. 6958, 61 Fed. Reg. 60,007","url":"https://www.govinfo.gov/link/fr/61/60007","by":{"0":"36, 38"}},{"t":"reg","label":"Proclamation No. 7524, 67 Fed. Reg. 8857","url":"https://www.govinfo.gov/link/fr/67/8857","by":{"0":"37"}},{"t":"reg","label":"Proclamation No. 7750, 69 Fed. Reg. 2287","url":"https://www.govinfo.gov/link/fr/69/2287","by":{"0":"43"}},{"t":"reg","label":"Proclamation No. 8015, 71 Fed. Reg. 28,541","url":"https://www.govinfo.gov/link/fr/71/28541","by":{"0":"38"}},{"t":"reg","label":"Proclamation No. 8342, 74 Fed. Reg. 4093","url":"https://www.govinfo.gov/link/fr/74/4093","by":{"0":"39"}},{"t":"reg","label":"Proclamation No. 8693, 76 Fed. Reg. 44,751","url":"https://www.govinfo.gov/link/fr/76/44751","by":{"0":"37"}},{"t":"reg","label":"Proclamation No. 8697, 76 Fed. Reg. 49,277","url":"https://www.govinfo.gov/link/fr/76/49277","by":{"0":"43"}},{"t":"reg","label":"Proclamation No. 9645, 82 Fed. Reg. 45,161","url":"https://www.govinfo.gov/link/fr/82/45161","by":{"0":"2","2":"1"}},{"t":"reg","label":"and rule—Continued:, 82 Fed. Reg. 56,100","url":"https://www.govinfo.gov/link/fr/82/56100","by":{"0":"3"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"0":"75"}},{"t":"case","label":"Ariz. Christian Schs. Tuition Org. v. Winn","cite":"563 U.S. 125","y":2011,"id":"2010/09-987","sc":1,"sum":"The Court held that the plaintiffs lacked standing because the Arizona tuition tax credit does not involve the appropriation or expenditure of state funds.","sumSrc":"Oyez","by":{"1":"27","2":"5"}},{"t":"case","label":"Bond v. United States","cite":"134 S. Ct. 2077","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Bryan v. United States","cite":"524 U.S. 184","y":1998,"id":"1997/96-8422","sc":1,"sum":"The Court held that the term \"willfully\" in section 924(a)(1)(D) requires proof only that the defendant knew his conduct was unlawful, not that he also knew of the federal licensing requirement.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"78, 79, 80"}},{"t":"case","label":"Carlson v. Landon","cite":"342 U.S. 524","y":1952,"id":"scdb/1951-054","sc":1,"sum":"1. Under § 20 (a) of the Immigration Act, as amended by § 23 of the Internal Security Act, the Attorney General may, in his discretion, hold in custody without bail, pending determination as to their deportability, aliens who are members of the Communist Party of the United States, when there is reasonable cause to believe that their release on bail would endanger the safety and welfare of the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35, 52"}},{"t":"case","label":"Chamber of Commerce v. Reich","cite":"74 F.3d 1322","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/74/1322/","by":{"1":"26"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"ar":2,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Clarke v. Sec. Indus. Ass’n","cite":"479 U.S. 388","y":1987,"id":"1986/85-971","sc":1,"sum":"Petitioner Security Pacific National Bank (Security Pacific) applied to the Comptroller of the Currency for permission to establish an affiliate named Discount Brokerage, and to offer discount brokerage services not only at its branch offices but also at other locations inside and outside of its home State. A pertinent branching provision of the National Bank Act, 12 U. S. C. § 81, originally enacted in 1927 as part …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"sum":"The Court held that the International Emergency Economic Powers Act constituted a specific congressional authorization for the President to order the transfer of Iranian assets. The Court further held that although the IEEPA itself did not authorize the presidential suspension of legal claims, previous acts of Congress had \"implicitly approved\" of executive control of claim settlement.","sumSrc":"Oyez","by":{"1":"21, 40, 50, 60","2":"3"}},{"t":"case","label":"Dep’t of Transp. v. Pub. Citizen","cite":"541 U.S. 752","y":2004,"id":"2003/03-358","sc":1,"sum":"The Court held that the FMCSA had no control of the trucks once the regulations were passed, and would therefore be unable to act on the findings of an EIS even if it did conduct one. Further, the Court found that the passage of the regulations was not sufficiently responsible for the increased pollution caused by the trucks to warrant an EIS.","sumSrc":"Oyez","by":{"1":"59"}},{"t":"case","label":"Edwards v. Aguillard","cite":"482 U.S. 578","y":1987,"id":"1986/85-1513","sc":1,"sum":"The Court held that it was a violation of the Establishment Clause of the First Amendment to mandate the teaching of creation science when teaching evolution science.","sumSrc":"Oyez","by":{"1":"67"}},{"t":"case","label":"Estate of Thornton v. Caldor, Inc.","cite":"472 U.S. 703","y":1985,"id":"1984/83-1158","sc":1,"sum":"The Court held 8-to-1 that the Connecticut Sabbath observance statute was void, saying its \"unyielding weighing in favor of Sabbath observers over all other interests\" results in an unconstitutional mingling of church and state.","sumSrc":"Oyez","by":{"1":"28","2":"5"}},{"t":"case","label":"Galvan v. Levine","cite":"490 F.2d 1255","y":1973,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/490/1255/","by":{"1":"79"}},{"t":"case","label":"Gibbons v. Ogden","cite":"9 Wheat. 1","y":1824,"url":"https://www.courtlistener.com/c/Wheat./9/1/","sum":"Recognizing that the power over “migration” was part of Congress’s power over foreign commerce.","sumSrc":"brief:1","by":{"1":"4"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Gratz v. Bollinger","cite":"539 U.S. 244","y":2003,"id":"2002/02-516","sc":1,"sum":"The Court held that the University of Michigan's practice of favoring applicants of certain races in the admissions process violated the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Gulf States Utils. Co. v. Fed. Power Comm’n","cite":"411 U.S. 747","y":1973,"id":"1972/71-1178","sc":1,"sum":"Following petitioner's application under § 204 of the Federal Power Act to respondent Federal Power Commission (FPC) for authorization of a bond issue, two intervening cities opposed the authorization on the ground that the proceeds of the bond issue would be used to finance or refinance certain anticompetitive activities in violation of the antitrust laws, the Federal Power Act, and the Public Utility Holding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Haig v. Agee","cite":"453 U.S. 280","id":"1980/80-83","sc":1,"sum":"In a 7-to-2 decision, the Court held that Passport Act of 1926 and other congressional statutes implicitly granted the Secretary of State the power to revoke passports.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"ar":3,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Hawaii v. Trump","cite":"245 F. Supp. 3d 1227","y":2017,"court":"D. Haw.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/245/1227/","by":{"1":"9"}},{"t":"case","label":"INS v. Nat’l Ctr. for Immigrants’ Rights, Inc.","cite":"502 U.S. 183","y":1991,"id":"1991/90-1090","sc":1,"sum":"The regulation on its face is consistent with the Attorney General's statutory authority.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34, 35"}},{"t":"case","label":"Int’l Refugee Assistance Project v. Trump","cite":"241 F. Supp. 3d 539","y":2017,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/241/539/","by":{"1":"9"}},{"t":"case","label":"Int’l Refugee Assistance Project v. Trump","cite":"265 F. Supp. 3d 570","y":2017,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/265/570/","by":{"1":"14"}},{"t":"case","label":"Int’l Refugee Assistance Project v. Trump","cite":"883 F.3d 223","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/223/","sum":"Observing that the “President’s own deputy press secretary” linked EO-3 to the “President Trump’s tweet[ing of] extremist anti-Muslim videos”.","sumSrc":"brief:1","by":{"1":"passim"}},{"t":"case","label":"Jean v. Nelson","cite":"472 U.S. 846","y":1985,"id":"1984/84-5240","sc":1,"sum":"Because the current statutes and regulations provide petitioners with nondiscriminatory parole consideration, there was no need for the Court of Appeals to address the constitutional issue, but it properly remanded the case to the District Court. On remand, the District Court must consider (1) whether INS officials exercised their discretion under the statute to make individualized parole determinations, and (2) …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"23, 24, 58","2":"10"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"sum":"The Court held that the policy used to determine whether a resident alien is able to ask for relief from deportation under a repealed portion of immigration laws is “arbitrary and capricious” under the Administrative Procedure Act, 5 U.S.C. § 706(2)(A).","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Korematsu v. United States","cite":"323 U.S. 214","y":1944,"id":"1940-1955/323us214","sc":1,"sum":"The Court held that compulsory exclusion of citizens during times of war is justified in order to reduce the risk of espionage.","sumSrc":"Oyez","by":{"1":"53"}},{"t":"case","label":"Larkin v. Grendel’s Den, Inc.","cite":"459 U.S. 116","y":1982,"id":"1982/81-878","sc":1,"sum":"Section 16C violates the Establishment Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29","2":"5"}},{"t":"case","label":"Law v. Siegel","cite":"134 S. Ct. 1188","y":2014,"id":"2013/12-5196","sc":1,"sum":"The Court found that a bankruptcy court may not enforce specific statutory exceptions.","sumSrc":"Oyez","by":{"1":"58"}},{"t":"case","label":"Lee v. Weisman","cite":"505 U.S. 577","y":1992,"id":"1991/90-1014","sc":1,"sum":"The Court held that a Rhode Island public school bringing in a rabbi to offer prayers at a graduation ceremony violated the First Amendment.","sumSrc":"Oyez","by":{"1":"27, 30"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"134 S. Ct. 1377","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Lloyd Sabaudo Societa Anonima Per Azioni v. Elting","cite":"287 U.S. 329","y":1932,"id":"scdb/1932-015","sc":1,"by":{"1":"23","2":"3"}},{"t":"case","label":"Locke v. Davey","cite":"540 U.S. 712","y":2004,"id":"2003/02-1315","sc":1,"sum":"The Court ruled that a state does not violate the First Amendment's free exercise clause when it funds secular college majors but excludes devotional theology majors.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"135 S. Ct. 1645","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1645/","sc":1,"by":{"1":"23"}},{"t":"case","label":"Mahler v. Eby","cite":"264 U.S. 32","y":1924,"id":"scdb/1923-058","sc":1,"sum":"1. The inhibition of ex post facto laws, (Const. Art. I, § 9) applies only to criminal laws, and not to a law for deporting aliens who by conviction of crime are shown to be undesirable as residents of this country.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"34, 39, 52","2":"11"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","by":{"1":"18"}},{"t":"case","label":"Match-E-Be-Nash-She-Wish Band of Pottawatomi Indians v. Patchak","cite":"567 U.S. 209","y":2012,"id":"2011/11-246","sc":1,"sum":"The Court held that a neighbor of a proposed Indian casino had standing to sue the government for taking 147 acres of a town's land under Section 465 of the Indian Reorganization Act.","sumSrc":"Oyez","by":{"1":"25, 26"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"62"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"1":"3"}},{"t":"case","label":"N.Y. Cent. Sec. Corp. v. United States","cite":"287 U.S. 12","y":1932,"id":"scdb/1932-039","sc":1,"sum":"(.1) Under subdivision (2) the Commission may authorize a carrier that already controls others by stock ownership, to have control also by lease, for the purpose of securing greater economy and efficiency of operation. The disjunctive phrasing, \"either under a lease or by purchase of stock,\" does not mean that one method must be exclusive of the other. Pp. 22-23. (2) The extent of control allowable by the Commission …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Nat’l Broad. Co. v. United States","cite":"319 U.S. 190","y":1943,"id":"scdb/1942-051","sc":1,"sum":"1. The regulatory powers of the Federal Communications Commission are not limited to the engineering and technical aspects of radio communication.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"134 S. Ct. 2550","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2550/","sc":1,"sum":"Recognizing importance of history in interpreting Establishment Clause.","sumSrc":"brief:1","by":{"1":"61"}},{"t":"case","label":"North Carolina v. Covington","cite":"137 S. Ct. 1624","y":2017,"id":"2016/16-1023","sc":1,"sum":"The Court determined that ordering equitable relief in a redistricting case requires that a court consider the severity and nature of the constitutional violation, the extent of the likely disruption to the ordinary processes of governance if early elections are imposed, and the need to act with proper judicial restraint when intruding on state sovereignty.","sumSrc":"Oyez","by":{"1":"80"}},{"t":"case","label":"Nw. Austin Mun. Util. Dist. No. 1 v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Romer v. Evans","cite":"517 U.S. 620","y":1996,"id":"1995/94-1039","sc":1,"sum":"The Court found a Colorado amendment that banned protection from discrimination based on sexual orientation violated the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"71"}},{"t":"case","label":"Salazar v. Buono","cite":"559 U.S. 700","y":2010,"id":"2009/08-472","sc":1,"sum":"The Court held that an individual has standing to maintain a suit when he acquires a \"judicially cognizable\" interest in ensuring compliance with a previous judgment in his favor. The Court also held that a court may not order an injunction in a case when it fails to consider all the circumstances bearing on the need for preventive relief.","sumSrc":"Oyez","by":{"1":"63"}},{"t":"case","label":"Santa Fe Indep. Sch. Dist. v. Doe","cite":"530 U.S. 290","y":2000,"id":"1999/99-62","sc":1,"sum":"The Court held that a public school district's policy permitting student-led, student-initiated prayer at football games violated the Establishment Clause.","sumSrc":"Oyez","by":{"1":"68, 77","2":"30"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"39, 60"}},{"t":"case","label":"Sprint/United Mgmt. Co. v. Mendelsohn","cite":"552 U.S. 379","y":2008,"id":"2007/06-1221","sc":1,"sum":"The Court vacated the Tenth Circuit's ruling and remanded the case for further proceedings. The Tenth Circuit, according to the Court, acted incorrectly when it engaged in its own assessment of the relevance and prejudicial effect of the witness testimony.","sumSrc":"Oyez","by":{"1":"74"}},{"t":"case","label":"Sullivan v. Zebley","cite":"493 U.S. 521","y":1990,"id":"1989/88-1377","sc":1,"sum":"The child-disability regulations are inconsistent with the statutory standard of \"comparable severity.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"77","2":"30"}},{"t":"case","label":"Town of Greece v. Galloway","cite":"134 S. Ct. 1811","y":2014,"id":"2013/12-696","sc":1,"sum":"The Court ruled that the invocation of prayer at a legislative session does not violate the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"passim"}},{"t":"case","label":"Trump v. Int’l Refugee Assistance Project","cite":"137 S. Ct. 2080","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/2080/","sc":1,"by":{"1":"10, 19"}},{"t":"case","label":"Two Guys from Harrison-Allentown, Inc. v. McGinley","cite":"366 U.S. 582","y":1961,"id":"1960/36","sc":1,"sum":"Appellant, a corporation operating a large discount department store located on a highway in a suburban section of Lehigh County, Pa., sued in a Federal District Court to enjoin enforcement of certain Pennsylvania Sunday Closing Laws, claiming that they were unconstitutional and that the County Disfrict Attorney was discriminating against it. One was a 1939 statute whichprohibited all worldly employment or business …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29","2":"5"}},{"t":"case","label":"U.S. Army Corps of Eng’rs v. Hawkes Co.","cite":"136 S. Ct. 1807","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1807/","sc":1,"by":{"1":"25"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"58"}},{"t":"case","label":"United States v. Lowden","cite":"308 U.S. 225","y":1939,"id":"scdb/1939-002","sc":1,"sum":"Section 5 (4) (b) of the Interstate Commerce Act provides that the Commission may authorize carriers to consolidate or lease their properties where it finds that that action, subject to such conditions and modifications as it shall find to be just and reasonable, will be in harmony with and in furtherance of the plan of consolidation of railway properties established pursuant to paragraph (3) of that section and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"United States v. Windsor","cite":"133 S. Ct. 2675","y":2013,"id":"2012/12-307","sc":1,"sum":"The Court found that the Defense of Marriage Act (DOMA) was unconstitutional under the equal protection clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"1":"67"}},{"t":"case","label":"Util. Air Regulatory Grp. v. EPA","cite":"134 S. Ct. 2427","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2427/","sc":1,"sum":"Recognizing importance of history in interpreting Establishment Clause.","sumSrc":"brief:1","by":{"1":"31, 77"}},{"t":"case","label":"W. Va. State Bd. of Educ. v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"sum":"The Court found that a West Virginia statute requiring students and teachers say the Pledge of Allegiance, under threat of expulsion and delinquency charges, was unconstitutional.","sumSrc":"Oyez","by":{"1":"76"}},{"t":"case","label":"Washington v. Trump","cite":"2017 WL 462040","y":2017,"court":"W.D. Wash. Feb. 3","by":{"1":"8"}},{"t":"case","label":"Washington v. Trump","cite":"847 F.3d 1151","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/1151/","by":{"1":"8"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"37, 51"}},{"t":"case","label":"Whole Woman’s Health v. Hellerstedt","cite":"136 S. Ct. 2292","y":2016,"id":"2015/15-274","sc":1,"sum":"The Court determined that the regulations at issue unconstitutionally imposed an undue burden on women seeking abortions because they created a substantial burden and did not actually serve the stated government interest.","sumSrc":"Oyez","by":{"1":"79"}},{"t":"case","label":"Wong Wing Hang v. INS","cite":"360 F.2d 715","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/360/715/","by":{"1":"45"}},{"t":"case","label":"Zelman v. Simmons-Harris","cite":"536 U.S. 639","y":2002,"id":"2001/00-1751","sc":1,"sum":"The Court held that Ohio’s Pilot Project Scholarship Program did not violate the Establishment Clause while providing school tuition vouchers eligible for use at religiously-affiliated schools.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"1":"4"}},{"t":"const","label":"Article I, Section 8, Clause 4","clauses":[["naturalization-bankruptcy","Naturalization and Bankruptcy Clause"]],"text":"To establish an uniform Rule of Naturalization, and uniform Laws on the subject of Bankruptcies throughout the United States;","by":{"1":"4, 78"}},{"t":"const","label":"Article I, Section 9, Clause 1","text":"The Migration or Importation of such Persons as any of the States now existing shall think proper to admit, shall not be prohibited by the Congress prior to the Year one thousand eight hundred and eight, but a Tax or duty may be imposed on such Importation, not exceeding ten dollars for each Person.","by":{"1":"4"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"3, 67","2":"passim"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)"],"by":{"1":"20"}},{"t":"usc","label":"50 U.S.C. § 21","url":"https://www.law.cornell.edu/uscode/text/50/21","stext":{"head":"§21. Restraint, regulation, and removal","paras":[[0,"Whenever there is a declared war between the United States and any foreign nation or government, or any invasion or predatory incursion is perpetrated, attempted, or threatened against the territory of the United States by any foreign nation or government, and the President makes public proclamation of the event, all natives, citizens, denizens, or subjects of the hostile nation or government, being of the age of fourteen years and upward, who shall be within the United States and not actually naturalized, shall be liable to be apprehended, restrained, secured, and removed as alien enemies. The President is authorized in any such event, by his proclamation thereof, or other public act, to direct the conduct to be observed on the part of the United States, toward the aliens who become so liable; the manner and degree of the restraint to which they shall be subject and in what cases, and upon what security their residence shall be permitted, and to provide for the removal of those who, not being permitted to reside within the United States, refuse or neglect to depart therefrom; and to establish any other regulations which are found necessary in the premises and for the public safety."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/21?type=usc&year=mostrecent&link-type=html"},"head":"§21. Restraint, regulation, and removal","tname":"War and National Defense","by":{"1":"60","2":"21"}},{"t":"law","label":"Pub. L. No. 114-113","url":"https://www.govinfo.gov/link/plaw/114/public/113","by":{"1":"49"}},{"t":"law","label":"Pub. L. No. 107-173","url":"https://www.govinfo.gov/link/plaw/107/public/173","by":{"1":"49"}},{"t":"law","label":"Pub. L. No. 95-105","by":{"1":"41"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"1":"59"}},{"t":"law","label":"Pub. L. No. 82-414","by":{"1":"passim"}},{"t":"law","label":"Pub. L. No. 99-603","by":{"1":"78"}},{"t":"law","label":"Pub. L. No. 110-53","url":"https://www.govinfo.gov/link/plaw/110/public/53","by":{"1":"49"}},{"t":"law","label":"Pub. L. No. 108-458","url":"https://www.govinfo.gov/link/plaw/108/public/458","by":{"1":"48, 49"}},{"t":"law","label":"Pub. L. No. 83-203","by":{"1":"47"}},{"t":"law","label":"Pub. L. No. 87-301","by":{"1":"24"}},{"t":"reg","label":"22 C.F.R. § 58.53","url":"https://www.ecfr.gov/current/title-22/section-58.53","by":{"1":"39"}},{"t":"case","label":"Centeno v. Shultz","cite":"817 F.2d 1212","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/817/1212/","by":{"2":"3"}},{"t":"case","label":"De Castro v. Fairman","cite":"164 Fed. Appx. 930","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./164/930/","by":{"2":"3"}},{"t":"case","label":"IRAP v. Trump","cite":"883 F.3d 233","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/233/","by":{"2":"27, 29"}},{"t":"case","label":"National Archives & Records Admin. v. Favish","cite":"541 U.S. 157","y":2004,"id":"2003/02-954","sc":1,"sum":"The Court held that the Foster family's interest in privacy outweighed the public interest in seeing pictures from Vincent Foster's death scene. The public interest could only trump privacy interests if Favish could present evidence that the government might have acted improperly. Favish failed to do so.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Rajah v. Mukasey","cite":"544 F.3d 427","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/544/427/","by":{"2":"22"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"134 S. Ct. 2427","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Washington v. Trump","cite":"858 F.3d 1168","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/858/1168/","by":{"2":"22"}},{"t":"law","label":"Pub. L. No. 89-236","url":"https://www.govinfo.gov/link/statute/79/911","by":{"2":"19"}},{"t":"reg","label":"Proclamation No. 9690, 83 Fed. Reg. 3057","url":"https://www.govinfo.gov/link/fr/83/3057","by":{"2":"29"}},{"t":"reg","label":"Proclamation No. 9723, 83 Fed. Reg. 15,937","url":"https://www.govinfo.gov/link/fr/83/15937","by":{"2":"10"}}]};